CREATE VIEW v_categories AS SELECT c.*,c.xmin::text version,c.created_at::date date,CASE WHEN c.is_active THEN 'Active' ELSE 'Archived' END status,(SELECT count(*) FROM products p WHERE p.category_id=c.id) products FROM categories c;
CREATE VIEW v_products AS SELECT p.*,p.xmin::text version,p.created_at::date date,c.name category,r.n reserved,p.current_stock-r.n available,coalesce(p.low_stock_threshold,s.low_stock_threshold) threshold,
 CASE WHEN p.current_stock=0 THEN 'Out of stock' WHEN p.current_stock<=coalesce(p.low_stock_threshold,s.low_stock_threshold) THEN 'Low stock' ELSE 'In stock' END stock_status,CASE WHEN p.is_active THEN 'Active' ELSE 'Archived' END status
 FROM products p LEFT JOIN categories c ON c.id=p.category_id CROSS JOIN system_settings s CROSS JOIN LATERAL (SELECT reserved_units(p.id) n) r;
CREATE VIEW v_customers AS SELECT c.*,c.xmin::text version,c.created_at::date date,CASE WHEN c.is_active THEN 'Active' ELSE 'Archived' END status,(SELECT count(*) FROM orders WHERE customer_id=c.id) orders FROM customers c;
CREATE VIEW v_stock_ins AS SELECT s.*,s.received_date date,coalesce((SELECT sum(quantity) FROM stock_in_items WHERE stock_in_id=s.id),0) quantity FROM stock_ins s;
CREATE VIEW v_stock_outs AS SELECT s.*,p.name product,s.out_date date FROM stock_outs s JOIN products p ON p.id=s.product_id;
CREATE VIEW v_orders AS SELECT o.*,o.xmin::text version,o.order_no reference_no,o.order_date date,coalesce(c.full_name,nullif(o.cash_customer_name,''),'Cash customer') customer,(SELECT sum(quantity) FROM order_items WHERE order_id=o.id) quantity FROM orders o LEFT JOIN customers c ON c.id=o.customer_id;
CREATE VIEW v_returns AS SELECT r.*,r.xmin::text version,r.return_no reference_no,r.return_date date,o.order_no,o.customer_id,o.customer,(SELECT sum(quantity) FROM return_items WHERE return_id=r.id) quantity FROM returns r JOIN v_orders o ON o.id=r.order_id;
CREATE VIEW v_adjustments AS SELECT a.*,a.adjustment_date date,p.name product FROM stock_adjustments a JOIN products p ON p.id=a.product_id;
CREATE VIEW v_movements AS SELECT m.*,p.name product,m.occurred_at date,CASE WHEN m.quantity>0 THEN 'in' ELSE 'out' END direction,
 CASE WHEN m.movement_type='OrderOut' THEN CASE WHEN o.customer_type='Cash' THEN 'Cash' ELSE 'Order' END WHEN m.movement_type='GiftOut' THEN 'Gift' WHEN m.movement_type='SampleOut' THEN 'Sample' ELSE m.movement_type END type,
 o.customer_id,coalesce(o.customer,so.recipient_name) recipient_name,coalesce(o.status,so.status,si.status) status FROM stock_movements m JOIN products p ON p.id=m.product_id LEFT JOIN v_orders o ON m.source_type='orders' AND o.id=m.source_id LEFT JOIN stock_outs so ON m.source_type='stock-outs' AND so.id=m.source_id LEFT JOIN stock_ins si ON m.source_type='stock-ins' AND si.id=m.source_id;
CREATE VIEW v_dispatches AS SELECT * FROM v_movements WHERE movement_type IN ('OrderOut','SampleOut','GiftOut');
CREATE VIEW v_audit AS SELECT a.*,a.created_at::date date,u.full_name admin FROM audit_logs a LEFT JOIN admin_users u ON u.id=a.admin_id;
CREATE VIEW v_backups AS SELECT id,file_name,file_size,checksum_sha256,type,status,verified_at,started_at,completed_at,error_message,started_at::date date FROM backups;
CREATE VIEW v_damaged AS SELECT i.id,r.reference_no,r.order_no,r.customer,r.customer_id,r.status,r.date,p.name product,i.product_id,i.quantity,r.reason,r.id return_id FROM return_items i JOIN v_returns r ON r.id=i.return_id JOIN products p ON p.id=i.product_id WHERE i.condition='Damaged' AND r.status='Approved';
CREATE VIEW v_low_stock AS SELECT * FROM v_products WHERE is_active AND stock_status='Low stock';
CREATE VIEW v_out_of_stock AS SELECT * FROM v_products WHERE is_active AND current_stock=0;
CREATE FUNCTION view_for(res text) RETURNS text LANGUAGE sql IMMUTABLE AS $$ SELECT CASE res WHEN 'products' THEN 'v_products' WHEN 'stock' THEN 'v_products' WHEN 'categories' THEN 'v_categories' WHEN 'low-stock' THEN 'v_low_stock' WHEN 'out-of-stock' THEN 'v_out_of_stock' WHEN 'customers' THEN 'v_customers' WHEN 'stock-ins' THEN 'v_stock_ins' WHEN 'stock-outs' THEN 'v_stock_outs' WHEN 'dispatches' THEN 'v_dispatches' WHEN 'orders' THEN 'v_orders' WHEN 'returns' THEN 'v_returns' WHEN 'stock-adjustments' THEN 'v_adjustments' WHEN 'damaged-items' THEN 'v_damaged' WHEN 'stock-movements' THEN 'v_movements' WHEN 'audit-logs' THEN 'v_audit' WHEN 'backups' THEN 'v_backups' END $$;
CREATE FUNCTION stock_list(res text, f jsonb DEFAULT '{}') RETURNS jsonb LANGUAGE plpgsql STABLE AS $$
DECLARE v text:=view_for(res); n int:=greatest(1,coalesce((f->>'page')::int,1)); sz int:=least(100,greatest(1,coalesce((f->>'pageSize')::int,20))); result jsonb;
BEGIN IF v IS NULL THEN RAISE NO_DATA_FOUND; END IF;
 EXECUTE format($query$WITH matches AS (SELECT id,to_jsonb(t) j FROM %I t WHERE ($1->>'from' IS NULL OR date>=($1->>'from')::date) AND ($1->>'to' IS NULL OR date<=($1->>'to')::date)), filtered AS (
 SELECT * FROM matches WHERE NOT EXISTS(SELECT 1 FROM jsonb_each_text($1) p WHERE p.key IN ('status','type','customer_type','stock_status','category_id','customer_id','product_id','is_active','direction','action','entity_type','order_id') AND p.value<>'' AND j->>p.key IS DISTINCT FROM p.value)
 AND (coalesce($1->>'q','')='' OR strpos(lower(concat_ws(' ',j->>'name',j->>'sku',j->>'full_name',j->>'reference_no',j->>'product',j->>'customer',j->>'recipient_name',j->>'source_name',j->>'description',j->>'file_name',j->>'phone')),lower($1->>'q'))>0)), counted AS (SELECT count(*) total FROM filtered)
 SELECT jsonb_build_object('items',coalesce((SELECT jsonb_agg(j ORDER BY id DESC) FROM (SELECT j,id FROM filtered ORDER BY id DESC LIMIT $3 OFFSET (($2::bigint-1)*$3)) page),'[]'::jsonb),'page',$2,'pageSize',$3,'totalCount',total,'totalPages',ceil(total::numeric/$3)::int) FROM counted$query$,v) INTO result USING f,n,sz;
 RETURN result; END $$;
CREATE FUNCTION stock_detail(res text,eid int) RETURNS jsonb LANGUAGE plpgsql STABLE AS $$
DECLARE v text:=view_for(res); j jsonb; lines jsonb;
BEGIN IF v IS NULL THEN RAISE NO_DATA_FOUND; END IF; EXECUTE format('SELECT to_jsonb(t) FROM %I t WHERE id=$1',v) INTO j USING eid; IF j IS NULL THEN RAISE NO_DATA_FOUND; END IF;
 IF res='orders' THEN SELECT jsonb_agg(to_jsonb(i)||jsonb_build_object('product',p.name,'sku',p.sku,'returnable',i.quantity-i.returned_qty-coalesce((SELECT sum(ri.quantity) FROM return_items ri JOIN returns r ON r.id=ri.return_id WHERE ri.order_item_id=i.id AND r.status='Pending'),0)) ORDER BY i.id) INTO lines FROM order_items i JOIN products p ON p.id=i.product_id WHERE i.order_id=eid;
 ELSIF res='stock-ins' THEN SELECT jsonb_agg(to_jsonb(i)||jsonb_build_object('product',p.name,'sku',p.sku) ORDER BY i.id) INTO lines FROM stock_in_items i JOIN products p ON p.id=i.product_id WHERE i.stock_in_id=eid;
 ELSIF res='returns' THEN SELECT jsonb_agg(to_jsonb(i)||jsonb_build_object('product',p.name,'sku',p.sku) ORDER BY i.id) INTO lines FROM return_items i JOIN products p ON p.id=i.product_id WHERE i.return_id=eid; END IF;
 RETURN j||CASE WHEN lines IS NULL THEN '{}'::jsonb ELSE jsonb_build_object('items',lines) END;
END $$;
CREATE FUNCTION stock_integrity() RETURNS jsonb LANGUAGE sql STABLE AS $$ WITH discrepancies AS (SELECT p.id,p.name,p.current_stock,coalesce(sum(m.quantity),0) ledger FROM products p LEFT JOIN stock_movements m ON m.product_id=p.id GROUP BY p.id HAVING p.current_stock<>coalesce(sum(m.quantity),0) OR p.current_stock<reserved_units(p.id)) SELECT jsonb_build_object('ok',count(*)=0,'discrepancies',coalesce(jsonb_agg(d),'[]'::jsonb),'checked_at',now()) FROM discrepancies d $$;
CREATE FUNCTION dashboard_summary() RETURNS jsonb LANGUAGE sql STABLE AS $$
 SELECT jsonb_build_object('products',count(*) FILTER(WHERE is_active),'on_hand',coalesce(sum(current_stock),0),'reserved',coalesce(sum(reserved),0),'available',coalesce(sum(available),0),
 'low_stock',count(*) FILTER(WHERE is_active AND stock_status='Low stock'),'out_of_stock',count(*) FILTER(WHERE is_active AND current_stock=0),'customers',(SELECT count(*) FROM customers WHERE is_active),
 'today_in',coalesce((SELECT sum(quantity) FROM v_movements WHERE date=business_today() AND quantity>0),0),'today_out',coalesce((SELECT sum(-quantity) FROM v_movements WHERE date=business_today() AND quantity<0),0),'today_orders',(SELECT count(*) FROM orders WHERE order_date=business_today() AND status<>'Cancelled'),
 'activity',stock_list('audit-logs','{"pageSize":5}')->'items','alerts',stock_list('low-stock','{"pageSize":5}')->'items','date',business_today(),'movements',stock_list('stock-movements','{"pageSize":5}')->'items') FROM v_products $$;
